//! miniq: a small in-memory message queue service.
//!
//! The service reads one JSON command per line and answers each with one JSON line (see `SPEC.md`).
//! [`Service`] turns a single line into a single response; [`run`] drives it over a byte stream.

mod error;

use std::io::{self, BufRead, Write};

use serde_json::{Map, Value, json};

pub use error::{Error, ErrorCode};

/// The whole state of a miniq process.
#[derive(Debug, Default)]
pub struct Service {}

impl Service {
    pub fn new() -> Self {
        Self::default()
    }

    /// Executes one command line (without its trailing `\n`) and returns the response line (also
    /// without `\n`).
    pub fn handle_line(&mut self, line: &[u8]) -> String {
        let response = match self.execute(line) {
            Ok(mut members) => {
                members.insert("ok".to_owned(), Value::Bool(true));
                Value::Object(members)
            }
            Err(error) => json!({ "ok": false, "error": error }),
        };
        response.to_string()
    }

    fn execute(&mut self, line: &[u8]) -> Result<Map<String, Value>, Error> {
        let _ = line;
        Err(Error::invalid_request("not implemented"))
    }
}

/// Answers every line of `input` on `output`, flushing after each response, until end of input.
pub fn run(mut input: impl BufRead, mut output: impl Write) -> io::Result<()> {
    let mut service = Service::new();
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        let response = service.handle_line(&line);
        output.write_all(response.as_bytes())?;
        output.write_all(b"\n")?;
        output.flush()?;
    }
}

