            attributes,
            messages: BTreeMap::new(),
            next_key: 0,
            last_sequence_number: 0,
            by_sent_at: BTreeSet::new(),
            hidden: BTreeSet::new(),
            eligible: BTreeSet::new(),
            groups: HashMap::new(),
            receipts: HashMap::new(),
            dedup: Deduplicator::default(),
        }
    }

