#![allow(dead_code)] // Each test binary uses a different subset of these helpers.

use miniq::Service;
use serde_json::{Value, json};

/// A miniq service driven one JSON command at a time.
#[derive(Default)]
pub struct Session {
    service: Service,
}

impl Session {
    pub fn new() -> Self {
        Self::default()
    }

    /// Sends a raw line and returns the parsed response.
    pub fn raw(&mut self, line: &[u8]) -> Value {
        let response = self.service.handle_line(line);
        assert!(!response.contains('\n'), "response spans lines: {response}");
        serde_json::from_str(&response).expect("response is JSON")
    }

    /// Sends a command and returns the parsed response, success or not.
    pub fn call(&mut self, command: Value) -> Value {
        self.raw(command.to_string().as_bytes())
    }

    /// Sends a command that must succeed and returns its response without the `ok` member.
    pub fn ok(&mut self, command: Value) -> Value {
        let mut response = self.call(command.clone());
        assert_eq!(response["ok"], true, "{command} failed: {response}");
        response.as_object_mut().unwrap().remove("ok");
        response
    }

    /// Sends a command that must fail and returns its error code.
    pub fn err(&mut self, command: Value) -> String {
        let response = self.call(command.clone());
        assert_eq!(response["ok"], false, "{command} should fail: {response}");
        let error = &response["error"];
        assert!(error["message"].is_string(), "error without message: {response}");
        error["code"].as_str().expect("string error code").to_owned()
    }

    pub fn create(&mut self, name: &str, attributes: Value) {
        self.ok(json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes}));
    }

    pub fn tick(&mut self, seconds: u64) {
        self.ok(json!({"Command": "Tick", "Seconds": seconds}));
    }

    pub fn send(&mut self, queue: &str, body: &str) -> String {
        let response = self.ok(json!({"Command": "SendMessage", "QueueName": queue, "Body": body}));
        response["MessageId"].as_str().unwrap().to_owned()
    }

    pub fn send_fifo(&mut self, queue: &str, body: &str, group: &str) -> Value {
        self.ok(json!({
            "Command": "SendMessage", "QueueName": queue, "Body": body,
            "GroupId": group, "DeduplicationId": body,
        }))
    }

    pub fn receive(&mut self, queue: &str, max: u64) -> Vec<Value> {
        let response = self.ok(json!({"Command": "ReceiveMessage", "QueueName": queue, "MaxMessages": max}));
        response["Messages"].as_array().unwrap().clone()
    }

    pub fn receive_with_timeout(&mut self, queue: &str, max: u64, timeout: u64) -> Vec<Value> {
        let response = self.ok(json!({
            "Command": "ReceiveMessage", "QueueName": queue,
            "MaxMessages": max, "VisibilityTimeout": timeout,
        }));
        response["Messages"].as_array().unwrap().clone()
    }

    pub fn attributes(&mut self, queue: &str) -> Value {
        self.ok(json!({"Command": "GetQueueAttributes", "QueueName": queue}))
    }

    pub fn counts(&mut self, queue: &str) -> (u64, u64, u64) {
        let counts = &self.attributes(queue)["Counts"];
        let get = |name: &str| counts[name].as_u64().unwrap();
        (get("Visible"), get("InFlight"), get("Delayed"))
    }
}

pub fn bodies(messages: &[Value]) -> Vec<&str> {
    messages.iter().map(|m| m["Body"].as_str().unwrap()).collect()
}

pub fn handle(message: &Value) -> &str {
    message["ReceiptHandle"].as_str().unwrap()
}

//! Protocol, error precedence and queue commands (SPEC sections 1, 2, 4 and 5).

mod common;

use common::Session;
use serde_json::json;

#[test]
fn malformed_lines_are_invalid_requests_and_the_session_continues() {
    let mut s = Session::new();
    for line in [&b""[..], b"  ", b"nope", b"[1]", b"{\"Command\": 3}", b"{\"Command\": \"Nope\"}", b"\xff"] {
        let response = s.raw(line);
        assert_eq!(response["error"]["code"], "InvalidRequest", "{line:?}");
    }
    s.tick(1);
}

#[test]
fn success_responses_carry_exactly_the_result_members() {
    let mut s = Session::new();
    assert_eq!(
        s.call(json!({"Command": "CreateQueue", "QueueName": "q"})),
        json!({"ok": true})
    );
    assert_eq!(
        s.call(json!({"Command": "Tick", "Seconds": 7})),
        json!({"ok": true, "Now": 7})
    );
}

#[test]
fn error_precedence_follows_section_2() {
    let mut s = Session::new();
    // Missing beats invalid, invalid beats lookup, lookup beats the command's own rules.
    assert_eq!(
        s.err(json!({"Command": "SendMessage", "QueueName": 1})),
        "MissingParameter"
    );
    assert_eq!(
        s.err(json!({"Command": "SendMessage", "QueueName": "nope", "Body": ""})),
        "InvalidParameterValue"
    );
    assert_eq!(
        s.err(json!({"Command": "SendMessage", "QueueName": "nope", "Body": "b", "GroupId": "g"})),
        "QueueDoesNotExist"
    );
    assert_eq!(
        s.err(json!({"Command": "DeleteMessage", "QueueName": "nope", "ReceiptHandle": "bogus"})),
        "QueueDoesNotExist"
    );
    assert_eq!(
        s.err(json!({"Command": "SetQueueAttributes", "QueueName": "nope", "Attributes": {"Fifo": true}})),
        "QueueDoesNotExist"
    );
}

#[test]
fn create_queue_defaults_and_get_attributes() {
    let mut s = Session::new();
    s.create("q", json!({}));
    assert_eq!(
        s.attributes("q"),
        json!({
            "Attributes": {
                "VisibilityTimeout": 30, "DelaySeconds": 0, "RetentionSeconds": 345600,
                "Fifo": false, "ContentBasedDeduplication": false,
            },
            "Counts": {"Visible": 0, "InFlight": 0, "Delayed": 0},
        })
    );
}

#[test]
fn create_queue_rules_in_order() {
    let mut s = Session::new();
    let create = |name: &str, attributes| json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes});

    assert_eq!(s.err(create("q.fifo", json!({}))), "QueueNameInvalid");
    assert_eq!(s.err(create("q", json!({"Fifo": true}))), "QueueNameInvalid");
    assert_eq!(
        s.err(create("q", json!({"ContentBasedDeduplication": true}))),
        "InvalidParameterValue"
    );
    assert_eq!(
        s.err(create("q", json!({"MaxReceiveCount": 3}))),
        "InvalidParameterValue"
    );
    assert_eq!(
        s.err(create("q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 3}))),
        "QueueDoesNotExist"
    );
    s.create("dlq.fifo", json!({"Fifo": true}));
    assert_eq!(
        s.err(create("q", json!({"DeadLetterQueue": "dlq.fifo", "MaxReceiveCount": 3}))),
        "InvalidParameterValue"
    );
    s.create("q.fifo", json!({"Fifo": true, "DeadLetterQueue": "dlq.fifo", "MaxReceiveCount": 3}));
}

#[test]
fn create_queue_is_idempotent_only_for_equal_attributes() {
    let mut s = Session::new();
    s.create("q", json!({"VisibilityTimeout": 10}));
    s.create("q", json!({"VisibilityTimeout": 10, "DelaySeconds": 0}));
    let again = json!({"Command": "CreateQueue", "QueueName": "q"});
    assert_eq!(s.err(again), "QueueAlreadyExists");
}

#[test]
fn queue_limit_is_1000() {
    let mut s = Session::new();
    for i in 0..1000 {
        s.create(&format!("q{i}"), json!({}));
    }
    s.create("q0", json!({})); // Existing queue with equal attributes still succeeds.
    assert_eq!(
        s.err(json!({"Command": "CreateQueue", "QueueName": "extra"})),
        "LimitExceeded"
    );
}

#[test]
fn list_queues_filters_by_prefix_in_byte_order() {
    let mut s = Session::new();
    for name in ["b", "a_x", "aZ", "a-1", "a9", "a.fifo", "ab"] {
        let fifo = name.ends_with(".fifo");
        s.create(name, json!({"Fifo": fifo}));
    }
    let all = s.ok(json!({"Command": "ListQueues"}));
    assert_eq!(
        all["QueueNames"],
        json!(["a-1", "a.fifo", "a9", "aZ", "a_x", "ab", "b"])
    );
    let some = s.ok(json!({"Command": "ListQueues", "Prefix": "a"}));
    assert_eq!(some["QueueNames"].as_array().unwrap().len(), 6);
    let none = s.ok(json!({"Command": "ListQueues", "Prefix": "c"}));
    assert_eq!(none["QueueNames"], json!([]));
}

#[test]
fn set_queue_attributes_rules_in_order() {
    let mut s = Session::new();
    s.create("q", json!({}));
    s.create("other", json!({}));
    s.create("f.fifo", json!({"Fifo": true}));
    let set = |attributes| json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": attributes});

    assert_eq!(
        s.err(json!({"Command": "SetQueueAttributes", "QueueName": "q"})),
        "MissingParameter"
    );
    assert_eq!(s.err(set(json!({"Fifo": false}))), "UnsupportedOperation");
    assert_eq!(
        s.err(set(json!({"ContentBasedDeduplication": true}))),
        "InvalidParameterValue"
    );
    assert_eq!(s.err(set(json!({"DeadLetterQueue": "other"}))), "InvalidParameterValue");
    assert_eq!(
        s.err(set(json!({"DeadLetterQueue": "gone", "MaxReceiveCount": 1}))),
        "QueueDoesNotExist"
    );
    assert_eq!(
        s.err(set(json!({"DeadLetterQueue": "q", "MaxReceiveCount": 1}))),
        "InvalidParameterValue"
    );
    assert_eq!(
        s.err(set(json!({"DeadLetterQueue": "f.fifo", "MaxReceiveCount": 1}))),
        "InvalidParameterValue"
    );

    s.ok(set(json!({})));
    s.ok(set(json!({"VisibilityTimeout": 5, "DeadLetterQueue": "other", "MaxReceiveCount": 2})));
    let attributes = &s.attributes("q")["Attributes"];
    assert_eq!(attributes["VisibilityTimeout"], 5);
    assert_eq!(attributes["DelaySeconds"], 0);
    assert_eq!(attributes["DeadLetterQueue"], "other");
    assert_eq!(attributes["MaxReceiveCount"], 2);
}

#[test]
fn deleting_a_queue_clears_dead_letter_configs_that_name_it() {
    let mut s = Session::new();
    s.create("dlq", json!({}));
    s.create("q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1}));
    s.send("dlq", "old");
    s.ok(json!({"Command": "DeleteQueue", "QueueName": "dlq"}));
    assert!(s.attributes("q")["Attributes"].get("DeadLetterQueue").is_none());
    assert!(s.attributes("q")["Attributes"].get("MaxReceiveCount").is_none());

    // A queue recreated under the same name starts empty.
    s.create("dlq", json!({}));
    assert_eq!(s.counts("dlq"), (0, 0, 0));
    assert_eq!(
        s.err(json!({"Command": "DeleteQueue", "QueueName": "missing"})),
        "QueueDoesNotExist"
    );
}

#[test]
fn purge_removes_messages_but_keeps_sequence_and_deduplication() {
    let mut s = Session::new();
    s.create("q.fifo", json!({"Fifo": true}));
    assert_eq!(s.send_fifo("q.fifo", "a", "g")["SequenceNumber"], 1);
    s.receive("q.fifo", 1);
    s.ok(json!({"Command": "PurgeQueue", "QueueName": "q.fifo"}));
    assert_eq!(s.counts("q.fifo"), (0, 0, 0));
    // Still a duplicate of the purged message.
    assert_eq!(s.send_fifo("q.fifo", "a", "g"), json!({"MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(s.send_fifo("q.fifo", "b", "g")["SequenceNumber"], 2);
}

#[test]
fn tick_advances_the_clock() {
    let mut s = Session::new();
    assert_eq!(s.ok(json!({"Command": "Tick", "Seconds": 0})), json!({"Now": 0}));
    assert_eq!(s.ok(json!({"Command": "Tick", "Seconds": 1209600})), json!({"Now": 1209600}));
    assert_eq!(s.err(json!({"Command": "Tick", "Seconds": 1209601})), "InvalidParameterValue");
    assert_eq!(s.err(json!({"Command": "Tick"})), "MissingParameter");
}

//! Message commands, time, retention and dead-letter queues (SPEC sections 3, 4 and 6).

mod common;

use common::{Session, bodies, handle};
use serde_json::json;

#[test]
fn ids_count_across_queues_and_skip_failed_sends() {
    let mut s = Session::new();
    s.create("a", json!({}));
    s.create("b", json!({}));
    assert_eq!(s.send("a", "1"), "m-1");
    s.err(json!({"Command": "SendMessage", "QueueName": "a", "Body": "x", "GroupId": "g"}));
    assert_eq!(s.send("b", "2"), "m-2");

    let a = s.receive("a", 1);
    let b = s.receive("b", 1);
    assert_eq!(handle(&a[0]), "r-1");
    assert_eq!(handle(&b[0]), "r-2");
}

#[test]
fn received_message_shape() {
    let mut s = Session::new();
    s.create("q", json!({}));
    s.tick(3);
    s.send("q", "hello");
    s.tick(2);
    let messages = s.receive("q", 10);
    assert_eq!(
        messages,
        [json!({
            "MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "hello",
            "ReceiveCount": 1, "SentAt": 3, "FirstReceivedAt": 5,
        })]
    );
}

#[test]
fn delays_hide_messages_until_they_end() {
    let mut s = Session::new();
    s.create("q", json!({"DelaySeconds": 10}));
    s.send("q", "queue-delay");
    s.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "own-delay", "DelaySeconds": 0}));
    assert_eq!(s.counts("q"), (1, 0, 1));
    assert_eq!(bodies(&s.receive("q", 10)), ["own-delay"]);
    s.tick(9);
    assert_eq!(s.receive("q", 10), []);
    s.tick(1);
    assert_eq!(bodies(&s.receive("q", 10)), ["queue-delay"]);
}

#[test]
fn visibility_timeout_returns_messages_in_arrival_order() {
    let mut s = Session::new();
    s.create("q", json!({"VisibilityTimeout": 10}));
    for body in ["a", "b", "c"] {
        s.send("q", body);
    }
    assert_eq!(bodies(&s.receive("q", 1)), ["a"]);
    assert_eq!(bodies(&s.receive("q", 1)), ["b"]);
    assert_eq!(s.counts("q"), (1, 2, 0));
    s.tick(10);
    let again = s.receive("q", 10);
    assert_eq!(bodies(&again), ["a", "b", "c"]);
    assert_eq!(again[0]["ReceiveCount"], 2);
    assert_eq!(again[0]["FirstReceivedAt"], 0);
}

#[test]
fn zero_visibility_timeout_never_yields_a_usable_handle() {
    let mut s = Session::new();
    s.create("q", json!({}));
    s.send("q", "a");
    let messages = s.receive_with_timeout("q", 10, 0);
    assert_eq!(messages.len(), 1);
    let delete = json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": handle(&messages[0])});
    assert_eq!(s.err(delete), "ReceiptHandleExpired");
    assert_eq!(s.counts("q"), (1, 0, 0));
}

#[test]
fn receipt_handles_are_checked_exactly() {
    let mut s = Session::new();
    s.create("q", json!({}));
    s.create("other", json!({}));
    s.send("q", "a");
    let first = s.receive("q", 1);
    let delete = |queue: &str, handle: &str| json!({"Command": "DeleteMessage", "QueueName": queue, "ReceiptHandle": handle});

    for bogus in ["r-01", "R-1", "r-1 ", "r-2", "r-0", "r-", "r-+1", "1"] {
        assert_eq!(s.err(delete("q", bogus)), "ReceiptHandleInvalid", "{bogus:?}");
    }
    assert_eq!(s.err(delete("other", "r-1")), "ReceiptHandleExpired");

    // Redelivery makes the old handle stale.
    s.tick(30);
    let second = s.receive("q", 1);
    assert_eq!(s.err(delete("q", handle(&first[0]))), "ReceiptHandleExpired");
    s.ok(delete("q", handle(&second[0])));
    assert_eq!(s.err(delete("q", handle(&second[0]))), "ReceiptHandleExpired");
    assert_eq!(s.counts("q"), (0, 0, 0));
}

#[test]
fn change_message_visibility_resets_the_timeout_from_now() {
    let mut s = Session::new();
    s.create("q", json!({}));
    s.send("q", "a");
    let message = s.receive("q", 1).remove(0);
    let change = |timeout: u64| json!({
        "Command": "ChangeMessageVisibility", "QueueName": "q",
        "ReceiptHandle": handle(&message), "VisibilityTimeout": timeout,
    });
    s.tick(20);
    s.ok(change(100));
    s.tick(99);
    assert_eq!(s.counts("q"), (0, 1, 0));
    s.ok(change(0));
    assert_eq!(s.counts("q"), (1, 0, 0));
    assert_eq!(s.err(change(10)), "ReceiptHandleExpired");
    let again = s.receive("q", 1);
    assert_eq!(again[0]["ReceiveCount"], 2);
}

#[test]
fn retention_removes_messages_whatever_their_state() {
    let mut s = Session::new();
    s.create("q", json!({"RetentionSeconds": 60}));
    s.send("q", "old");
    s.tick(30);
    s.send("q", "new");
    s.receive("q", 1);
    s.tick(30);
    assert_eq!(s.counts("q"), (1, 0, 0));
    assert_eq!(bodies(&s.receive("q", 10)), ["new"]);
}

#[test]
fn lowering_retention_removes_messages_at_once_for_good() {
    let mut s = Session::new();
    s.create("q", json!({}));
    s.send("q", "a");
    s.tick(100);
    let set = |seconds: u64| json!({
        "Command": "SetQueueAttributes", "QueueName": "q",
        "Attributes": {"RetentionSeconds": seconds},
    });
    s.ok(set(60));
    assert_eq!(s.counts("q"), (0, 0, 0));
    s.ok(set(1000));
    assert_eq!(s.counts("q"), (0, 0, 0));
}

#[test]
fn queue_attribute_changes_apply_to_later_operations_only() {
    let mut s = Session::new();
    s.create("q", json!({"DelaySeconds": 5}));
    s.send("q", "a");
    s.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"DelaySeconds": 0, "VisibilityTimeout": 1}}));
    assert_eq!(s.counts("q"), (0, 0, 1));
    s.tick(5);
    s.receive("q", 1);
    s.tick(1);
    assert_eq!(s.counts("q"), (1, 0, 0));
}

#[test]
fn send_rules_by_queue_type() {
    let mut s = Session::new();
    s.create("std", json!({}));
    s.create("q.fifo", json!({"Fifo": true}));
    let send = |queue: &str, extra: serde_json::Value| {
        let mut command = json!({"Command": "SendMessage", "QueueName": queue, "Body": "b"});
        command.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
        command
    };
    assert_eq!(s.err(send("std", json!({"DeduplicationId": "d"}))), "UnsupportedOperation");
    assert_eq!(s.err(send("q.fifo", json!({"DelaySeconds": 0, "GroupId": "g"}))), "UnsupportedOperation");
    assert_eq!(s.err(send("q.fifo", json!({"DeduplicationId": "d"}))), "MissingParameter");
    assert_eq!(s.err(send("q.fifo", json!({"GroupId": "g"}))), "MissingParameter");
    assert_eq!(
        s.ok(send("q.fifo", json!({"GroupId": "g", "DeduplicationId": "d"}))),
        json!({"MessageId": "m-1", "SequenceNumber": 1})
    );
}

#[test]
fn fifo_deduplication_window() {
    let mut s = Session::new();
    s.create("q.fifo", json!({"Fifo": true, "ContentBasedDeduplication": true}));
    let send = |body: &str, group: &str| json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": body, "GroupId": group});

    assert_eq!(s.ok(send("x", "g1")), json!({"MessageId": "m-1", "SequenceNumber": 1}));
    s.tick(299);
    // Duplicates ignore the group and do not extend the window.
    assert_eq!(s.ok(send("x", "g2")), json!({"MessageId": "m-1", "SequenceNumber": 1}));
    let message = s.receive("q.fifo", 1).remove(0);
    s.ok(json!({"Command": "DeleteMessage", "QueueName": "q.fifo", "ReceiptHandle": handle(&message)}));
    assert_eq!(s.ok(send("x", "g1")), json!({"MessageId": "m-1", "SequenceNumber": 1}));
    s.tick(1);
    assert_eq!(s.ok(send("x", "g1")), json!({"MessageId": "m-2", "SequenceNumber": 2}));
    // An explicit DeduplicationId takes precedence over the body.
    let explicit = json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": "x", "GroupId": "g", "DeduplicationId": "other"});
    assert_eq!(s.ok(explicit), json!({"MessageId": "m-3", "SequenceNumber": 3}));
}

#[test]
fn fifo_groups_deliver_in_order_one_at_a_time() {
    let mut s = Session::new();
    s.create("q.fifo", json!({"Fifo": true}));
    for (body, group) in [("a1", "a"), ("b1", "b"), ("a2", "a"), ("c1", "c")] {
        s.send_fifo("q.fifo", body, group);
    }
    let first = s.receive("q.fifo", 10);
    assert_eq!(bodies(&first), ["a1", "b1", "c1"]);
    assert_eq!(first[0]["GroupId"], "a");
    assert_eq!(first[0]["SequenceNumber"], 1);
    assert_eq!(s.receive("q.fifo", 10), []);

    s.ok(json!({"Command": "DeleteMessage", "QueueName": "q.fifo", "ReceiptHandle": handle(&first[0])}));
    assert_eq!(bodies(&s.receive("q.fifo", 10)), ["a2"]);
}

#[test]
fn messages_move_to_the_dead_letter_queue_after_max_receives() {
    let mut s = Session::new();
    s.create("dlq", json!({}));
    s.create("q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 2}));
    s.send("q", "poison");
    s.send("q", "fine");
    s.tick(5);
    for _ in 0..2 {
        assert_eq!(bodies(&s.receive_with_timeout("q", 1, 0)), ["poison"]);
    }
    // The poison message moves instead of being delivered and does not count toward MaxMessages.
    let messages = s.receive("q", 1);
    assert_eq!(bodies(&messages), ["fine"]);
    assert_eq!(s.counts("q"), (0, 1, 0));

    let moved = s.receive("dlq", 1);
    assert_eq!(moved[0]["MessageId"], "m-1");
    assert_eq!(moved[0]["SentAt"], 0);
    assert_eq!(moved[0]["ReceiveCount"], 1);
    assert_eq!(moved[0]["FirstReceivedAt"], 5);
}

#[test]
fn fifo_dead_letter_move_takes_a_new_sequence_number_and_unblocks_the_group() {
    let mut s = Session::new();
    s.create("dlq.fifo", json!({"Fifo": true}));
    s.create("q.fifo", json!({"Fifo": true, "DeadLetterQueue": "dlq.fifo", "MaxReceiveCount": 1}));
    s.send_fifo("dlq.fifo", "already-there", "z");
    s.send_fifo("q.fifo", "a1", "a");
    s.send_fifo("q.fifo", "a2", "a");
    s.receive_with_timeout("q.fifo", 1, 0);

    // a1 moves, so a2 is now first of its group and is delivered in the same receive.
    assert_eq!(bodies(&s.receive("q.fifo", 10)), ["a2"]);
    let moved = s.receive("dlq.fifo", 10);
    assert_eq!(bodies(&moved), ["already-there", "a1"]);
    assert_eq!(moved[1]["SequenceNumber"], 2);
    assert_eq!(moved[1]["GroupId"], "a");
}

#[test]
fn dead_letters_too_old_for_their_new_queue_vanish() {
    let mut s = Session::new();
    s.create("dlq", json!({"RetentionSeconds": 60}));
    s.create("q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1}));
    s.send("q", "a");
    s.receive_with_timeout("q", 1, 0);
    s.tick(60);
    assert_eq!(s.receive("q", 10), []);
    assert_eq!(s.counts("q"), (0, 0, 0));
    assert_eq!(s.counts("dlq"), (0, 0, 0));
}

#[test]
fn moved_messages_invalidate_their_receipt_handles() {
    let mut s = Session::new();
    s.create("dlq", json!({}));
    s.create("q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1}));
    s.send("q", "a");
    let message = s.receive_with_timeout("q", 1, 0).remove(0);
    s.receive("q", 1);
    let delete = json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": handle(&message)});
    assert_eq!(s.err(delete), "ReceiptHandleExpired");
}

#[test]
fn a_queue_holds_at_most_100000_messages() {
    let mut s = Session::new();
    s.create("q", json!({}));
    for _ in 0..100_000 {
        s.send("q", "x");
    }
    assert_eq!(
        s.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"})),
        "LimitExceeded"
    );
    assert_eq!(s.counts("q"), (100_000, 0, 0));
    // Receiving deep into a full queue stays cheap because receives skip in-flight messages.
    for _ in 0..1_000 {
        assert_eq!(s.receive("q", 10).len(), 10);
    }
}

//! Runs the real `miniq` binary over stdin/stdout.

use std::io::Write;
use std::process::{Command, Stdio};

fn run_miniq(input: &[u8]) -> (String, i32) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("miniq starts");
    child.stdin.take().unwrap().write_all(input).unwrap();
    let output = child.wait_with_output().unwrap();
    (
        String::from_utf8(output.stdout).expect("stdout is UTF-8"),
        output.status.code().expect("miniq exits normally"),
    )
}

#[test]
fn answers_every_line_in_order_and_exits_zero() {
    let input = concat!(
        "{\"Command\": \"CreateQueue\", \"QueueName\": \"jobs\"}\n",
        "\n",
        "{\"Command\": \"SendMessage\", \"QueueName\": \"jobs\", \"Body\": \"hi\"}\r\n",
        "{\"Command\": \"Tick\", \"Seconds\": 4}", // Final line without a newline still counts.
    );
    let (stdout, code) = run_miniq(input.as_bytes());
    assert_eq!(code, 0);
    let lines: Vec<serde_json::Value> = stdout
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    assert_eq!(lines.len(), 4);
    assert_eq!(lines[0], serde_json::json!({"ok": true}));
    assert_eq!(lines[1]["error"]["code"], "InvalidRequest");
    assert_eq!(lines[2]["MessageId"], "m-1");
    assert_eq!(lines[3], serde_json::json!({"ok": true, "Now": 4}));
    assert!(stdout.ends_with('\n'));
}

#[test]
fn empty_input_produces_no_output() {
    assert_eq!(run_miniq(b""), (String::new(), 0));
}

